package com.yeyamo_mobile.api.booking_service.infrastructure.outbox;import java.time.Instant;import java.util.UUID;import jakarta.persistence.*;@Entity@Table(name="booking_outbox")public class BookingOutboxEvent{@Id UUID id;@Column(name="aggregate_id",nullable=false,length=120)String aggregateId;@Column(name="event_type",nullable=false,length=140)String eventType;@Column(name="target_topic",nullable=false,length=140)String targetTopic;@Column(nullable=false,columnDefinition="TEXT")String payload;@Column(name="occurred_at",nullable=false)Instant occurredAt;@Column(name="published_at")Instant publishedAt;@Column(nullable=false)int attempts;@Column(name="last_error",length=1000)String lastError;}
